17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.advice.InvalidRequestException;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	import org.springframework.util.StringUtils;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        List<String> missingFields = new ArrayList<>();
106	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
107	            missingFields.add("firstName");
108	        }
109	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
110	            missingFields.add("lastName");
111	        }
112	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
113	            missingFields.add("address");
114	        }
115	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
116	            missingFields.add("city");
117	        }
118	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
119	            missingFields.add("telephone");
120	        }
121	        if (!missingFields.isEmpty()) {
122	            throw new InvalidRequestException(missingFields);
123	        }
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        // Normalize the telephone: strip every non-digit character, then require exactly 10 digits.
127	        String normalizedTelephone = owner.getTelephone().replaceAll("\\D", "");
128	        if (normalizedTelephone.length() != 10) {
129	            throw new InvalidRequestException(List.of("telephone"));
130	        }
131	        owner.setTelephone(normalizedTelephone);
132	        this.clinicService.saveOwner(owner);
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
142	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
143	        if (currentOwner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
151	        this.clinicService.saveOwner(currentOwner);
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Transactional
157	    @Override
158	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        this.clinicService.deleteOwner(owner);
164	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        HttpHeaders headers = new HttpHeaders();
175	        Pet pet = petMapper.toPet(petFieldsDto);
176	        owner.setId(ownerId);
177	        pet.setOwner(owner);
178	        pet.getType().setName(null);
179	        this.clinicService.savePet(pet);
180	        PetDto petDto = petMapper.toPetDto(pet);
181	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
182	            .buildAndExpand(pet.getId()).toUri());
183	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner != null) {
191	            Pet currentPet = this.clinicService.findPetById(petId);
192	            if (currentPet != null) {
193	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
194	                currentPet.setName(petFieldsDto.getName());
195	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
196	                this.clinicService.savePet(currentPet);
197	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
198	            }
199	        }
200	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
206	        HttpHeaders headers = new HttpHeaders();
207	        Visit visit = visitMapper.toVisit(visitFieldsDto);
208	        Pet pet = new Pet();
209	        pet.setId(petId);
210	        visit.setPet(pet);
211	        this.clinicService.saveVisit(visit);
212	        VisitDto visitDto = visitMapper.toVisitDto(visit);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
214	            .buildAndExpand(visit.getId()).toUri());
215	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
216	    }
217	
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	}
